function parseColor(raw: string, precise = false): RgbaColor & { cmyk?: readonly number[]; space?: "b-w" } {
  const s = raw.trim();
  const low = s.toLowerCase();
  if (X11_NAMED_COLORS[low]) {
    const [r, g, b, a] = X11_NAMED_COLORS[low]!;
    return { r, g, b, a, ...(low === "gray" || low === "grey" ? { space: "b-w" as const } : {}) };
  }
  const grayMatch = /^gr[ae]y(\d{1,3})$/.exec(low);
  if (grayMatch) {
    const level = Number(grayMatch[1]);
    // X11 names at 50 and 90 use lower samples than the corresponding percentages.
    const v = level === 50 ? 127 : level === 90 ? 229
      : Math.max(0, Math.min(255, Math.round((level / 100) * 255)));
    return { r: v, g: v, b: v, a: 255, space: "b-w" };
  }
  const round = (value: number) => precise ? value : Math.round(value);
  if (/^#[0-9a-f]{12}$/i.test(s)) {
    const r = round(parseInt(s.slice(1, 5), 16) / 257);
    const g = round(parseInt(s.slice(5, 9), 16) / 257);
    const b = round(parseInt(s.slice(9, 13), 16) / 257);
    return { r, g, b, a: 255 };
  }
  if (/^#[0-9a-f]{16}$/i.test(s)) {
    const r = round(parseInt(s.slice(1, 5), 16) / 257);
    const g = round(parseInt(s.slice(5, 9), 16) / 257);
    const b = round(parseInt(s.slice(9, 13), 16) / 257);
    const a = round(parseInt(s.slice(13, 17), 16) / 257);
    return { r, g, b, a };
  }
  const fnMatch = /^(s?rgba?|gr[ae]ya?|cmyka?|hs[bv]a?|hwba?|lab|cielab)\(\s*([^)]+)\s*\)$/i.exec(s);
  if (fnMatch) {
    const kind = fnMatch[1]!.toLowerCase();
    const parts = fnMatch[2]!.split(/[\s,]+/).filter(Boolean);
    if (kind === "lab" || kind === "cielab") {
      const components = parts.map(part => Number(part.endsWith("%") ? part.slice(0, -1) : part) * (part.endsWith("%") ? 2.55 : 1));
      if (components.length !== 3 || components.some(value => !Number.isFinite(value))) return baseParseColor(s);
      // Native percent components use the 0–255 scale, including lightness;
      // signed chroma is offset by (QuantumRange + 1) / 2.
      const conversion = convertHuePixels({
        width: 1, height: 1, data: new Uint8Array(4), format: "raw", space: "srgb",
        channels: 3, depth: "ushort", density: 72, hasAlpha: false, magickColorspace: "CIELab",
        hueSamples: new Float64Array([components[0]! / 100, components[1]! / 255 + 32768 / 65535, components[2]! / 255 + 32768 / 65535, 1]),
      }, "sRGB");
      let step = conversion.next();
      while (!step.done) step = conversion.next();
      const [r, g, b] = step.value.evaluateSamples!.slice(0, 3).map(value => round(Math.max(0, Math.min(255, value))));
      return { r: r!, g: g!, b: b!, a: 255 };
    }
    if (kind === "hwb" || kind === "hwba") {
      const components = parts.map(part => parseFloat(part) * (part.endsWith("%") ? 255 / 100 : 1));
      const hue = (((components[0] ?? 0) % 360 + 360) % 360) / 60;
      const white = (components[1] ?? 0) / 255, black = (components[2] ?? 0) / 255;
      // ImageMagick does not normalize whiteness + blackness above one.
      const chroma = 1 - white - black, x = chroma * (1 - Math.abs(hue % 2 - 1));
      const [r, g, b] = hue < 1 ? [chroma, x, 0] : hue < 2 ? [x, chroma, 0]
        : hue < 3 ? [0, chroma, x] : hue < 4 ? [0, x, chroma]
        : hue < 5 ? [x, 0, chroma] : [chroma, 0, x];
      const alpha = kind === "hwba" ? components[3] ?? 1 : 1;
      return {
        r: round(Math.max(0, Math.min(255, (r + white) * 255))),
        g: round(Math.max(0, Math.min(255, (g + white) * 255))),
        b: round(Math.max(0, Math.min(255, (b + white) * 255))),
        a: round(Math.max(0, Math.min(255, alpha * 255))),
      };
    }
    if (kind === "hsb" || kind === "hsv" || kind === "hsba" || kind === "hsva") {
      const components = parts.map(part => part.endsWith("%") ? Number(part.slice(0, -1)) / 100 * 255 : Number(part));
      if (components.length < 3 || components.length > 4 || components.some(value => !Number.isFinite(value))) return baseParseColor(s);
      const hue = ((components[0]! % 360) + 360) % 360 / 60;
      const saturation = components[1]! / 255, value = components[2]! / 255;
      const chroma = saturation * value, x = chroma * (1 - Math.abs(hue % 2 - 1)), m = value - chroma;
      const [r, g, b] = hue < 1 ? [chroma, x, 0] : hue < 2 ? [x, chroma, 0] : hue < 3 ? [0, chroma, x]
        : hue < 4 ? [0, x, chroma] : hue < 5 ? [x, 0, chroma] : [chroma, 0, x];
      return {
        r: round(Math.max(0, Math.min(255, (r + m) * 255))),
        g: round(Math.max(0, Math.min(255, (g + m) * 255))),
        b: round(Math.max(0, Math.min(255, (b + m) * 255))),
        a: kind.endsWith("a") ? round(Math.max(0, Math.min(255, (components[3] ?? 1) * 255))) : 255,
      };
    }
    const parseChanByte = (p: string | undefined, def = 0) => {
      if (!p) return def;
      if (p.endsWith("%")) {
        return Math.max(0, Math.min(255, round((parseFloat(p) / 100) * 255)));
      }
      return Math.max(0, Math.min(255, round(parseFloat(p))));
    };
    const parseAlphaByte = (p: string | undefined) => {
      if (!p) return 255;
      if (p.endsWith("%")) {
        return Math.max(0, Math.min(255, round((parseFloat(p) / 100) * 255)));
      }
      const num = parseFloat(p);
      return num <= 1 ? Math.max(0, Math.min(255, round(num * 255))) : Math.max(0, Math.min(255, round(num)));
    };
    if (kind.startsWith("gray") || kind.startsWith("grey")) {
      const v = parseChanByte(parts[0], 0);
      const a = parseAlphaByte(parts[1]);
      return { r: v, g: v, b: v, a, space: "b-w" };
    }
    if (kind.startsWith("cmyk")) {
      const parseUnit = (p: string | undefined) => {
        if (!p) return 0;
        if (p.endsWith("%")) return Math.max(0, Math.min(1, parseFloat(p) / 100));
        const num = parseFloat(p);
        return Math.max(0, Math.min(1, num / 255));
      };
      const c = parseUnit(parts[0]);
      const m = parseUnit(parts[1]);
      const y = parseUnit(parts[2]);
      const k = parseUnit(parts[3]);
      const a = parseAlphaByte(parts[4]);
      return {
        r: round(255 * (1 - c) * (1 - k)),
        g: round(255 * (1 - m) * (1 - k)),
        b: round(255 * (1 - y) * (1 - k)),
        a,
        cmyk: [c, m, y, k]
      };
    }
    const r = parseChanByte(parts[0], 0);
    const g = parseChanByte(parts[1], 0);
    const b = parseChanByte(parts[2], 0);
    const a = parseAlphaByte(parts[3]);
    return { r, g, b, a };
  }
  const hslMatch = /^hsla?\(\s*([+-]?[\d.]+)\s*,\s*([\d.]+)%?\s*,\s*([\d.]+)%?(?:\s*,\s*([\d.]+))?\s*\)$/i.exec(s);
  if (precise && hslMatch) {
    const hue = (((Number(hslMatch[1]) % 360) + 360) % 360) / 60;
    const saturation = Math.max(0, Math.min(100, Number(hslMatch[2]))) / 100;
    const lightness = Math.max(0, Math.min(100, Number(hslMatch[3]))) / 100;
    const chroma = (1 - Math.abs(2 * lightness - 1)) * saturation;
    const x = chroma * (1 - Math.abs(hue % 2 - 1)), m = lightness - chroma / 2;
    const [r, g, b] = hue < 1 ? [chroma, x, 0] : hue < 2 ? [x, chroma, 0]
      : hue < 3 ? [0, chroma, x] : hue < 4 ? [0, x, chroma]
      : hue < 5 ? [x, 0, chroma] : [chroma, 0, x];
    const alpha = hslMatch[4] === undefined ? 1 : Number(hslMatch[4]);
    return { r: (r + m) * 255, g: (g + m) * 255, b: (b + m) * 255,
      a: Math.max(0, Math.min(255, alpha <= 1 ? alpha * 255 : alpha)) };
  }
  return baseParseColor(s);
}

export interface ImagemagickLimits {
  readonly maxInputBytes: number;
}

export interface ImageMagickCommandOptions {
  readonly limits?: Partial<ImagemagickLimits>;
  readonly replace?: boolean;
}

export interface ImageMagickCliResult {
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
  readonly stdoutBytes?: Uint8Array;
}

export interface MagickGeometry {
  readonly width?: number;
  readonly height?: number;
  readonly x: number;
  readonly y: number;
  readonly hasOffset: boolean;
  readonly hasYOffset: boolean;
  readonly forceExact: boolean;
  readonly shrinkOnly: boolean;
  readonly enlargeOnly: boolean;
  readonly fillArea: boolean;
  readonly isPercent: boolean;
  readonly percentX?: number;
  readonly percentY?: number;
  readonly areaLimit?: number;
  readonly isSubdivide?: boolean;
  readonly aspectRatio?: number;
}

function normalizeMagickOffsets(raw: string): string {
    // An offset sign may precede a signed number, including hexadecimal offsets.
    let normalized = "";
    for (let i = 0; i < raw.length; i++) {
        let sign = raw[i]!;
        const previous = normalized.at(-1)?.toLowerCase();
        if ((sign === "+" || sign === "-") && (raw[i + 1] === "+" || raw[i + 1] === "-")
            && raw[i + 2]! >= "0" && raw[i + 2]! <= "9" && previous !== "e") {
            sign = sign === raw[++i] ? "+" : "-";
        }
        normalized += sign;
        if ((sign === "+" || sign === "-") && previous !== "e"
            && raw[i + 1] === "0" && raw[i + 2]?.toLowerCase() === "x") {
            let end = i + 3;
            while (end < raw.length && "0123456789abcdef".includes(raw[end]!.toLowerCase())) end++;
            if (end > i + 3) {
                normalized += Number.parseInt(raw.slice(i + 3, end), 16);
                i = end - 1;
            }
        }
    }
    return normalized;
}

export function parseMagickGeometry(raw: string): MagickGeometry {
  let s = normalizeMagickOffsets([...raw].filter(character => character.trim() !== "").join(""));
  // GetGeometry retains dimensions before an incomplete exponent or trailing backslash.
  if (s.endsWith("e") || s.endsWith("E") || s.endsWith("\\")) s = s.slice(0, -1);
  let forceExact = false;
  let shrinkOnly = false;
  let enlargeOnly = false;
  let fillArea = false;
  let isPercent = false;
  let isArea = false;

  while (s.length > 0) {
    const last = s[s.length - 1]!;
    if (last === "!") {
      forceExact = true;
      s = s.slice(0, -1);
    } else if (last === ">") {
      shrinkOnly = true;
      s = s.slice(0, -1);
    } else if (last === "<") {
      enlargeOnly = true;
      s = s.slice(0, -1);
    } else if (last === "^") {
      fillArea = true;
      s = s.slice(0, -1);
    } else if (last === "%") {
      isPercent = true;
      s = s.slice(0, -1);
    } else if (last === "@") {
      isArea = true;
      s = s.slice(0, -1);
    } else {
      break;
    }
  }

  let x = 0;
  let y = 0;
  let hasOffset = false;
  let hasYOffset = false;
  // A final sign leaves its ordinate at zero without discarding earlier fields.
  const trailingOffsetSign = s.endsWith("+") || s.endsWith("-");
  // Signs inside exponents belong to dimensions, not rectangle offsets.
  const offsetStart = [...s].findIndex((character, index) => (character === "+" || character === "-") && s[index - 1]?.toLowerCase() !== "e");
  // Rectangle geometry preserves the first two offsets and ignores later ones.
  const offsetMatch = offsetStart < 0 ? null : /^([+-](?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)(?:([+-](?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)(?:[+-](?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)*)?$/.exec(trailingOffsetSign ? `${s.slice(offsetStart)}0` : s.slice(offsetStart));
  if (offsetMatch) {
    // A bare second sign has no Y value; the synthetic zero only permits parsing.
    hasYOffset = offsetMatch[2] !== undefined && offsetStart + offsetMatch[1]!.length + 1 < s.length;
    s = s.slice(0, offsetStart);
    x = Number(offsetMatch[1]!);
    y = offsetMatch[2] !== undefined ? Number(offsetMatch[2]!) : 0;
    hasOffset = true;
  }

  while (s.length > 0) {
    const last = s[s.length - 1]!;
    if (last === "!") {
      forceExact = true;
      s = s.slice(0, -1);
    } else if (last === ">") {
      shrinkOnly = true;
      s = s.slice(0, -1);
    } else if (last === "<") {
      enlargeOnly = true;
      s = s.slice(0, -1);
    } else if (last === "^") {
      fillArea = true;
      s = s.slice(0, -1);
    } else if (last === "%") {
      isPercent = true;
      s = s.slice(0, -1);
    } else if (last === "@") {
      isArea = true;
      s = s.slice(0, -1);
    } else {
      break;
    }
  }

  if (s.includes(":")) {
    const parts = s.split(":");
    const ratio = Number(parts[0]) / Number(parts[1]);
    if (parts.length === 2 && Number(parts[0]) > 0 && Number(parts[1]) > 0 && Number.isFinite(ratio)) {
      return { aspectRatio: ratio, x, y, hasOffset, hasYOffset, forceExact, shrinkOnly, enlargeOnly, fillArea, isPercent: false };
    }
  }

  if (isArea) {
    if (s.includes("x") || s.includes("X")) {
      const [wStr, hStr] = s.split(/[xX]/);
      return {
        width: Math.max(1, Number(wStr) || 1),
        height: Math.max(1, Number(hStr) || 1),
        x,
        y,
        hasOffset,
        hasYOffset,
        forceExact,
        shrinkOnly,
        enlargeOnly,
        fillArea,
        isPercent: false,
        isSubdivide: true
      };
    }
    const areaLimit = Math.max(1, Number(s) || 1);
    return {
      areaLimit,
      x,
      y,
      hasOffset,
      hasYOffset,
      forceExact,
      shrinkOnly,
      enlargeOnly,
      fillArea,
      isPercent
    };
  }

  let width: number | undefined;
  let height: number | undefined;
  if (s.includes("x") || s.includes("X")) {
    let [wStr, hStr] = s.split(/[xX]/);
    if (wStr?.endsWith("%")) {
      isPercent = true;
      wStr = wStr.slice(0, -1);
    }
    if (hStr?.endsWith("%")) {
      isPercent = true;
      hStr = hStr.slice(0, -1);
    }
    if (wStr && wStr.length > 0) width = Number(wStr);
    if (hStr && hStr.length > 0) height = Number(hStr);
  } else if (s.length > 0) {
    width = Number(s);
  }

  if (isPercent) {
    const px = width ?? height ?? 100;
    const py = height ?? width ?? 100;
    return {
      ...(width !== undefined && !Number.isNaN(width) ? { width } : {}),
      ...(height !== undefined && !Number.isNaN(height) ? { height } : {}),
      percentX: px,
      percentY: py,
      x,
      y,
      hasOffset,
      hasYOffset,
      forceExact,
      shrinkOnly,
      enlargeOnly,
      fillArea,
      isPercent: true
    };
  }

  return {
    ...(width !== undefined && !Number.isNaN(width) ? { width } : {}),
    ...(height !== undefined && !Number.isNaN(height) ? { height } : {}),
    x,
    y,
    hasOffset,
    hasYOffset,
    forceExact,
    shrinkOnly,
    enlargeOnly,
    fillArea,
    isPercent: false
  };
}

function parseSelectiveBlurGeometry(raw: string): MagickGeometry {
    let normalized = "", dimensions = true;
    for (const character of raw) {
        if (character === "(" || character === ")") continue;
        if (character === "," || character === "/") {
            normalized += dimensions ? "x" : "+";
            dimensions = false;
        } else {
            normalized += character;
            if (character === "x" || character === "X") dimensions = false;
        }
    }
    return parseMagickGeometry(normalized);
}

function parseMagickSketchGeometry(raw: string): { width?: number; height?: number; x?: number } {
    validateMagickTransformGeometry(raw.replaceAll(",", "x"), "-sketch");
    if (!raw.includes(",")) return parseMagickGeometry(raw);
    const [width = 0, height = 1, x = 0] = raw.split(",").map(Number);
    return { width, height, x };
}

function parseDelay(value: string, ticksPerSecond = 100, current?: number): { milliseconds: number; ticksPerSecond: number; delayTicks: number } {
  const geometry = [...value].filter(character => !"%!^<>@()#".includes(character)).join("");
  const fields: string[] = [];
  let start = 0;
  for (let index = 1; index < geometry.length; index++) {
    if ("+-".includes(geometry[index]!) && !"eExX/,".includes(geometry[index - 1]!)) {
      fields.push(geometry.slice(start, index));
      start = index;
    }
  }
  fields.push(geometry.slice(start));
  // Preserve hexadecimal tick rates such as 0x2 in 12x0x2.
  const separator = [...fields[0]!].findIndex(character => "xX/,".includes(character));
  const parts = separator < 0 ? [fields[0]!] : [fields[0]!.slice(0, separator), fields[0]!.slice(separator + 1)];
  if (fields[0]!.includes(":")) {
    const ratio = fields[0]!.split(":");
    if (ratio.length === 2 && ratio.every(part => part.trim() && Number.isFinite(Number(part)))) {
      // ImageMagick ratio geometry divides rho by sigma and sets sigma to one.
      parts.splice(0, parts.length, String(Number(ratio[0]) / Number(ratio[1])), "1");
    }
  }
  if (!geometry.trim() || fields.length > 3 ||
      [...parts, ...fields.slice(1)].some(part => !Number.isFinite(Number(part)))) return { milliseconds: NaN, ticksPerSecond, delayTicks: 0 };
  const [delay, ticks] = parts;
  // A pair of signed offsets has no duration; a single signed number still does.
  let next = parts.length === 1 && fields.length > 1 && "+-".includes(geometry.trimStart().charAt(0))
    ? 0 : Math.round(Number(delay));
  if (current !== undefined) {
    const previous = Math.round(current * ticksPerSecond / 1000);
    if (value.includes(">")) next = Math.min(previous, next);
    // Native SetImageProperty uses sigma (zero when omitted) for the '<' assignment.
    else if (value.includes("<")) next = previous < next ? Math.round(Number(ticks ?? 0)) : previous;
  }
  if (ticks) ticksPerSecond = Math.round(Number(ticks)) || 1;
  return { milliseconds: Math.floor(next * 1000 / ticksPerSecond), ticksPerSecond, delayTicks: next };
}

function parseDelayOption(value: string, current: number): ReturnType<typeof parseDelay> {
  const delay = parseDelay(value);
  if (!Number.isFinite(delay.milliseconds)) {
    throw new Error(`invalid argument for option '-delay' '${value}'`);
  }
  validateMagickTransformGeometry(value, "-delay");
  // Incoming delays are stored in milliseconds at the default 100 ticks/second.
  if (value.includes(">")) delay.delayTicks = Math.min(current / 10, delay.delayTicks);
  else if (value.includes("<")) delay.delayTicks = Math.max(current / 10, delay.delayTicks);
  delay.milliseconds = Math.floor(delay.delayTicks * 1000 / delay.ticksPerSecond);
  return delay;
}

