                const working = yield { kind: "read", image: 1, position: ((y - top) * frame.width + start - left) * 4, length: (end - start) * 4, hue: sourceHue, evaluate: !sourceHue };
                const integers = highDepth ? new Uint16Array(input.slice().buffer) : input;
