function applyMagickProfile<T extends { readonly icc?: Uint8Array; readonly exif?: Uint8Array; readonly xmp?: Uint8Array; [magickInput]?: MagickFormatContext }>(image: T, name: string, profile?: Uint8Array): T {
    if (profile) {
        if (profile.length < 128 || String.fromCharCode(...profile.subarray(36, 40)) !== "acsp") throw new Error(`invalid ICC profile '${name}'`);
        return { ...image, icc: profile };
    }
    if (["xmp", "*"].includes(name.toLowerCase())) {
        const { xmp: ignored, ...rest } = image;
        image = rest as T;
    }
    if (["exif", "*"].includes(name.toLowerCase())) {
        const { exif, ...rest } = image;
        // Native keeps decoded text available for this invocation, without serializing it.
        image = exif ? { ...rest, [magickInput]: { ...image[magickInput], exifTextProperties: readExifTextProperties(exif) } } as T : rest as T;
    }
    if (["icc", "icm", "*"].includes(name.toLowerCase())) {
        const { icc: ignored, ...rest } = image;
        return rest as T;
    }
    return image;
}

async function tryConvertFiles(argv: readonly string[], input: ConvertFileInput, stdinBytes: Uint8Array | undefined, signal: AbortSignal, composite = false): Promise<ImageMagickCliResult | undefined> {
    const analysis = createConvertAnalysis(composite);
    try {
        const result = await tryConvertFilesResult(argv, input, stdinBytes, signal, analysis);
        return result ? combineConvertOutput(result, analysis) : undefined;
    } catch (error) {
        signal.throwIfAborted();
        if (!(error instanceof RangeError) || !["Invalid WebP frame duration", "Invalid WebP loop count"].includes(error.message)) throw error;
        return combineConvertOutput({ exitCode: 1, stdout: "", stderr: `magick: ${error.message}\n` }, analysis);
    }
}
